/* ---------- 9. Make the sample data follow the real date ----------
   Every date is moved by the same number of days, so the newest orders are TODAY.
   Example: on 20 Nov 2026 every date moves 13 days forward. */
(function shiftDates() {
  const shift = Math.round((Date.parse(APP_TODAY) - Date.parse(DATA_BASE_DATE)) / 864e5);
  if (!shift) return;
  const move = iso => new Date(Date.parse(iso) + shift * 864e5).toISOString().slice(0, 10);
  ORDERS.forEach(o => { o.date = move(o.date); });
  CUSTOMERS.forEach(c => { c.joined = move(c.joined); });
  STAFF.forEach(s => { s.joined = move(s.joined); });
  INVENTORY.forEach(i => { i.lastRestock = move(i.lastRestock); });
  STOCK_LOG.forEach(l => { l.date = move(l.date); });
  PURCHASE_ORDERS.forEach(p => { p.date = move(p.date); p.expected = move(p.expected); if (p.received) p.received = move(p.received); });
})();